import fs from 'node:fs/promises';
import { Workbook, SpreadsheetFile } from '@oai/artifact-tool';
const records=JSON.parse(await fs.readFile(new URL('./extrase-data.json',import.meta.url),'utf8'));
const wb=Workbook.create();
const sh=wb.worksheets.add('Extrase 2026');
sh.showGridLines=false;
sh.getRange('A1:N9').format.font={name:'Arial',size:10};
sh.getRange('A2').values=[['Extrase de cont primite de la Cosmina • 2026']];
sh.getRange('A2').format.font={size:14,bold:true};
sh.getRange('A3').values=[['Verificat la 20.10.2026 în Eva-Mail • 2 emailuri / 2 PDF-uri • datele primirii sunt în ora României']];
sh.getRange('A4').values=[['PDF-uri parolate; perioada este confirmată din email. Numele firmelor sunt păstrate mascate, ca în sursă.']];
const headers=['Primit la','Titular (din subiect)','Banca','Perioadă de la','Perioadă până la','Fișier atașat','Expeditor','Subiect email','Destinatari','Cont Eva-Mail','Dimensiune (octeți)','ID email Eva-Mail','ID atașament Eva-Mail','Observații'];
sh.getRange('A6:N6').values=[headers];
const serial=s=>Date.parse(s)/86400000+25569;
const rows=records.map(r=>[serial(r.received_at)+3/24,r.subject.replace('Fwd: Extras Lunar Banca Transilvania ',''),'Banca Transilvania',serial('2026-07-01'),serial('2026-07-31'),r.attachments[0].name,r.from_address,r.subject,r.to.join('; '),r.account_email,r.attachments[0].size,r.id,r.attachments[0].id,'PDF parolat; conținutul extrasului nu a fost citit.']);
sh.getRange('A7:N8').values=rows;
sh.tables.add('A6:N8',true,'Extrase2026');
sh.getRange('A6:N6').format={fill:'#243E58',font:{bold:true,color:'#FFFFFF'},wrapText:true,rowHeight:32};
sh.getRange('A7:N8').format.rowHeight=60;
sh.getRange('A7:N8').format.wrapText=true;
sh.getRange('A7:A8').format.numberFormat='dd.mm.yyyy hh:mm:ss';
sh.getRange('D7:E8').format.numberFormat='dd.mm.yyyy';
sh.getRange('K7:K8').format.numberFormat='#,##0';
const widths=[23,26,23,15,15,56,34,60,48,34,20,44,44,50];
widths.forEach((v,i)=>sh.getRangeByIndexes(5,i,3,1).format.columnWidth=v);
sh.freezePanes.freezeRows(6);
wb.recalculate();
console.log((await wb.inspect({kind:'table',range:'Extrase 2026!A6:F8',include:'values',tableMaxRows:3,tableMaxCols:6})).ndjson);
const preview=await wb.render({sheetName:'Extrase 2026',range:'A1:F9',scale:1.3});
await fs.writeFile(new URL('./preview.png',import.meta.url),new Uint8Array(await preview.arrayBuffer()));
const out='Z:/Dep. Contabilitate/Extrase de cont Cosmina/outputs/01a158de-077f-7f22-811e-78cf5c263291';
await fs.mkdir(out,{recursive:true});
await (await SpreadsheetFile.exportXlsx(wb)).save(out+'/Extrase_Cosmina_2026.xlsx');
console.log(out+'/Extrase_Cosmina_2026.xlsx');

